```
#include <stdio.h>
#include "csapp.h"
int main()
{
  printf("2");
  if (Fork())
  {
    printf("33");
    Write(STDOUT_FILENO, "lol", 3);
  }
  else
  {
    Sleep(1);
    printf("233");
    Write(STDOUT_FILENO, "hhhh", 4);
  }
  fflush(stdout);
  return 0;
}
```
